  }
  New-Item -ItemType Directory -Force -Path $Destination | Out-Null
  # 2026-09-21 (FAN-920 §28): the previous form
  #   Copy-Item -LiteralPath $item.FullName -Destination (Join-Path $Destination $item.Name) -Recurse -Force
