      "`n  ps1 不被接受: " + $(if($ps1NotAccepted){$ps1NotAccepted -join ', '}else{'(无)'}) +
      "`n  TS 未覆盖 ps1 分支: " + $(if($missingBranches){$missingBranches -join ', '}else{'(无)'}))
  }
