  if ($ps1Markers.Count -eq 0) { throw '前门: install-fan-host-payload.ps1 没有 FAN_HOST_*_OK 成功输出常量' }
  # 3b) fanHost.ts 侧成功判定正则：提取 "FAN_HOST_(ACL|PAYLOAD)_OK:" 字面量
